"""Generated from the registry: schemas/tools.toml (binding tools), schemas/tools.typed.json (the typed
tools' schemas: the snapshot tests compare), docs/tools/<domain>.md and the TOOLS.md block per domain.
`tool gen` writes them, `tool gen --check` (CI, tests) lists the stale ones.
"""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

from tools.core import Registry, Spec, load

TOML_HEADER = """\
# GENERATED by `tool gen` from packages/tools (domains/bindings.py): edit the registry there, never this file.
# The local commands a Telegram command or button may run without a brain turn. Read live (by mtime) by
# tg-adapter's bindings runner (adapters/tg/src/registry.ts) and by `tg-bind` (packages/tgadapter/bind.py).
#
# [tools."<name>"]
#   argv         the command, no shell (a leading ~/ in an element = $HOME); a binding's extra args and the owner's
#                text (text_arg) are appended
#   effect       read | home | send_owner | send_external | spend | irreversible   (in that order)
#                read: looks only · home: changes his own state (lights, lists, reminders, HA helpers) ·
#                send_owner: contacts only him · send_external: anyone else · spend: money · irreversible: no undo.
#                Effects gate: a tap or command never runs a tool above send_owner; such
#                input goes to the brain as a normal event.
#   timeout_s    default 20, at most 300
#   output       text | picture   (picture: stdout may be one {"photo", "caption", "text"} JSON object, 0.1.18 shape)
#   note         default for a binding's note: true = the brain also gets a short "answered" event
#   text_arg     a command binding takes the owner's "/name <text>" as ONE extra argument
#   description  one line: what the tool does
#   menu         the /commands menu line of a command bound to it (tg-bind command rows with a menu line make
#                the menu, in row order; set_commands adds the brain's own commands after them); absent = not listed
#   toast        what a bound tap's toast says (default "✓ <button text>")
#
# The plugin's compat tables (instant.json and callbacks.json, read as a fallback) run an entry only when its exact
# argv is registered here: an unregistered entry goes to the brain instead. Every compat use is counted
# (`tg-bind compat`).
schema = 1
"""
MD_BEGIN = "<!-- tool-docs:{d} begin (generated by `tool docs`; edit packages/tools) -->"
MD_END = "<!-- tool-docs:{d} end -->"


def _s(v: str) -> str:
    return json.dumps(v, ensure_ascii=False)  # a JSON string is a valid TOML basic string


def tools_toml(reg: Registry) -> str:
    out = [TOML_HEADER]
    for t in reg.argv.values():
        out.append(f"\n[tools.{_s(t.name)}]\nargv = [{', '.join(_s(a) for a in t.argv)}]\neffect = {_s(t.effect)}\n")
        if t.timeout_s is not None:
            out.append(f"timeout_s = {t.timeout_s}\n")
        if t.output is not None:
            out.append(f"output = {_s(t.output)}\n")
        if t.text_arg is not None:
            out.append(f"text_arg = {str(t.text_arg).lower()}\n")
        if t.note is not None:
            out.append(f"note = {str(t.note).lower()}\n")
        out.append(f"description = {_s(t.description)}\n")
        if t.menu is not None:
            out.append(f"menu = {_s(t.menu)}\n")
        if t.toast is not None:
            out.append(f"toast = {_s(t.toast)}\n")
    return "".join(out)


def spec_schema(s: Spec) -> dict[str, Any]:
    return {
        "mcp_name": s.mcp_name,
        "domain": s.domain,
        "summary": s.summary,
        "effect": s.effect,
        "approval": s.approval,
        "rate": s.rate,
        "labels_out": list(s.labels_out),
        "destructive": s.destructive,
        "idempotent": s.idempotent,
        "input": s.input.model_json_schema(),
        "output": s.output.model_json_schema(),
    }


def typed_json(reg: Registry) -> str:
    d = {"generated_by": "tool gen (packages/tools)", "tools": {n: spec_schema(s) for n, s in reg.typed.items()}}
    return json.dumps(d, indent=1, sort_keys=True, ensure_ascii=False) + "\n"


def _type(p: dict[str, Any]) -> str:
    if "enum" in p:
        return " | ".join(str(x) for x in p["enum"])
    if "anyOf" in p:
        ts = [_type(x) for x in p["anyOf"] if x.get("type") != "null"]
        return " | ".join(ts) + (" (optional)" if any(x.get("type") == "null" for x in p["anyOf"]) else "")
    if p.get("type") == "array":
        return f"list of {_type(p.get('items', {})) or 'items'}"
    if "$ref" in p:
        return p["$ref"].rsplit("/", 1)[-1]
    t = p.get("type", "")
    return t + (f" /{p['pattern']}/" if "pattern" in p else "")


def fields_md(schema: dict[str, Any], skip: tuple[str, ...] = ("format",)) -> list[str]:
    req = set(schema.get("required", []))
    out = []
    for name, p in schema.get("properties", {}).items():
        if name in skip:
            continue
        bits = [_type(p)] + (["required"] if name in req else [])
        if name not in req and p.get("default") not in (None, False, ""):
            bits.append(f"default {json.dumps(p['default'], ensure_ascii=False)}")
        out.append(
            f"- `{name}` ({', '.join(b for b in bits if b)})"
            + (f": {p['description']}" if p.get("description") else "")
        )
    return out


def domain_md(reg: Registry, domain: str) -> str:
    d = reg.domains[domain]
    specs = reg.in_domain(domain)
    out = [
        f"# {d.title} tools",
        "",
        d.summary,
        "",
        f"Generated by `tool gen` from packages/tools (domains/{domain}.py): edit the registry, not this file. "
        "MCP server `hub` (tool `mcp__hub__<MCP name>`) and `tool call NAME '<json>' [--json]` run the same gateway "
        "and return the same result. Every input also takes `format`: concise (default) | detailed. Errors: "
        "{code, message, hint}; codes invalid_args, not_found, conflict, unavailable, timeout, rate_limited, "
        "approval_required, failed, internal. Each call logs one usage event (via=gateway, trace id, ms, code).",
        "",
        "| Tool | MCP name | Effect | Approval | Rate | Output labels |",
        "|---|---|---|---|---|---|",
    ]
    for s in specs:
        out.append(
            f"| `{s.name}` | `{s.mcp_name}` | {s.effect}{' (destructive)' if s.destructive else ''} | "
            f"{s.approval if s.approval != 'none' else '—'} | {s.rate or '—'} | {', '.join(s.labels_out) or '—'} |"
        )
    for s in specs:
        out += ["", f"## {s.name}", "", s.doc, "", "Input:"]
        out += fields_md(s.input.model_json_schema()) or ["- (none)"]
        oschema = s.output.model_json_schema()
        detail = getattr(s.output, "DETAIL", ())
        out += [
            "",
            "Output: "
            + ", ".join(f"`{k}`" for k in oschema.get("properties", {}))
            + (f" (concise leaves out {', '.join(detail)})" if detail else ""),
        ]
        for ex in s.examples[:2]:
            out.append(f"Example: `tool call {s.name} '{json.dumps(ex, ensure_ascii=False)}'`")
    if d.notes:
        out += ["", "## CLI and cron", "", d.notes]
    return "\n".join(out) + "\n"


def tools_md_block(reg: Registry, domain: str) -> str:
    """The TOOLS.md lines for a domain: one line for the typed tools, then the domain's CLI notes (how to call them,
    typed errors and usage logging are said once in the TOOLS.md header, not per block)."""
    tools = []
    for s in reg.in_domain(domain):
        args = [n for n in s.input.model_json_schema().get("properties", {}) if n != "format"]
        tools.append(f"`{s.name}` {{{', '.join(args)}}}")
    line = f"- {reg.domains[domain].title} tools (`tool docs {domain}`): " + " · ".join(tools) + "."
    body = [MD_BEGIN.format(d=domain), line]
    if reg.domains[domain].notes:
        body.append("- " + reg.domains[domain].notes)
    body.append(MD_END.format(d=domain))
    return "\n".join(body)


def patch_tools_md(text: str, reg: Registry, domain: str) -> str:
    """TEXT with the domain's block replaced (the markers must already be there)."""
    b, e = MD_BEGIN.format(d=domain).split(" (")[0], MD_END.format(d=domain)
    i = text.find(b)
    j = text.find(e, i)
    if i < 0 or j < 0:
        raise ValueError(f"no {b} … {e} block in the file: add the two marker lines first")
    return text[:i] + tools_md_block(reg, domain) + text[j + len(e) :]


def outputs(reg: Registry) -> dict[str, str]:
    files = {"schemas/tools.toml": tools_toml(reg), "schemas/tools.typed.json": typed_json(reg)}
    for dom in reg.domains:
        if reg.in_domain(dom):
            files[f"docs/tools/{dom}.md"] = domain_md(reg, dom)
    return files


def stale(repo: Path, reg: Registry | None = None) -> list[str]:
    reg = reg or load()
    bad = []
    for rel, body in outputs(reg).items():
        p = repo / rel
        if not p.is_file() or p.read_text() != body:
            bad.append(rel)
    return bad


def write(repo: Path, reg: Registry | None = None) -> list[str]:
    reg = reg or load()
    changed = []
    for rel, body in outputs(reg).items():
        p = repo / rel
        if not p.is_file() or p.read_text() != body:
            p.parent.mkdir(parents=True, exist_ok=True)
            tmp = p.with_name(p.name + ".tmp")
            tmp.write_text(body)
            tmp.replace(p)
            changed.append(rel)
    return changed
